 function render(){let c=conversations[idx%conversations.length];$('#sentence').textContent=c.a;choices.innerHTML='';c.opts.forEach((o,i)=>{let b=document.createElement('button');b.className='choice';b.textContent=o;b.onclick=()=>answer(i,b,c);choices.appendChild(b)});}
